#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/image_list.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// NavigationPane's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/navigation_pane.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether the pane shows only its collapsed bar. Collapsing closes the configure menu; expanding closes the overlay.
template <typename Declaring>
struct NavigationPaneCollapsedCapability {
    PropertyView<bool, NavigationPaneCollapsedCapability<Declaring>> collapsed;

    static void assign(NavigationPaneCollapsedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.collapsed), std::move(incoming));
    }

    static bool read(const NavigationPaneCollapsedCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.collapsed);
        return current;
    }
};

// The number of large buttons the user chose; 4 by default. A count above PageSetLimits::maximum_capacity throws std::out_of_range.
template <typename Declaring>
struct NavigationPaneButtonCountCapability {
    PropertyView<std::size_t, NavigationPaneButtonCountCapability<Declaring>> button_count;

    static void assign(NavigationPaneButtonCountCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.button_count), std::move(incoming));
    }

    static std::size_t read(const NavigationPaneButtonCountCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.button_count);
        return current;
    }
};

// The width the pane asks for while expanded, and the overlay's width; 220 by default. A width outside 80 to 1024 throws std::out_of_range.
template <typename Declaring>
struct NavigationPaneExpandedWidthCapability {
    PropertyCell<double, NavigationPaneExpandedWidthCapability<Declaring>> expanded_width{220.0};

    static void assign(NavigationPaneExpandedWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.expanded_width), incoming);
        if (!capability.expanded_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.expanded_width));
    }
};

// Images for the pages' image_keys, or null. A disposed list or one bound to another window throws std::invalid_argument.
template <typename Declaring>
struct NavigationPaneImageListCapability {
    PropertyCell<std::shared_ptr<ImageList>, NavigationPaneImageListCapability<Declaring>> image_list{};

    static void assign(NavigationPaneImageListCapability& capability, std::shared_ptr<ImageList> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_list), incoming);
        if (!capability.image_list.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_list));
    }
};

// Whether the pane registers itself as an F6 region of its window while attached (owner decision RB-17); on by default.
template <typename Declaring>
struct NavigationPaneFocusRegionCapability {
    PropertyCell<bool, NavigationPaneFocusRegionCapability<Declaring>> focus_region{true};

    static void assign(NavigationPaneFocusRegionCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.focus_region), incoming);
        if (!capability.focus_region.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.focus_region));
    }
};

// Every NavigationPane capability, in the order the declaring class takes them.
template <typename Declaring>
struct NavigationPaneCapabilities : public NavigationPaneCollapsedCapability<Declaring>,
                                    public NavigationPaneButtonCountCapability<Declaring>,
                                    public NavigationPaneExpandedWidthCapability<Declaring>,
                                    public NavigationPaneImageListCapability<Declaring>,
                                    public NavigationPaneFocusRegionCapability<Declaring> {};

} // namespace gui_forms
